-- GenDB engine variant Q04-commuted_comparisons: template q04.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  o_orderpriority,
  COUNT(*) AS order_count
FROM orders
WHERE
  $1 <= o_orderdate
  AND $1 + INTERVAL '3 MONTH' > o_orderdate
  AND EXISTS(
    SELECT
      *
    FROM lineitem
    WHERE
      o_orderkey = l_orderkey AND l_receiptdate > l_commitdate
  )
GROUP BY
  o_orderpriority
ORDER BY
  o_orderpriority
